-- ---------------------------------------------------------------------------
-- Check: 143 rows from this file (100 ready), plus the 12 April
-- picture questions still image-pending from the 30 Sep seed.
-- ---------------------------------------------------------------------------

select split_part(external_ref, ':', 1) as paper,
       subject_id,
       status,
       count(*) as questions,
       string_agg(split_part(external_ref, ':', 2), ', ' order by length(external_ref), external_ref) as which
from questions
where external_ref like 'dim-2026-04-12-variant-a:%'
   or external_ref like 'dim-2026-04-26-variant-d:%'
group by 1, 2, 3
order by 1, 2, 3;
